window.docContents[137].resolve({"/rules/RG1007/#RG1007-rationale":{"contents":"A contract is useful only if it constrains the code callers run. A registration over f n for a fixed parameter, or over an ineligible constant, says nothing about the executable definition across its domain.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG1007: Executable contracts require supported closed evidence","header":"Why it matters","id":"/rules/RG1007/#RG1007-rationale"},"/rules/RG4004/#RG4004-rationale":{"contents":"Conforming claims reject compiler-trusting proofs (RG1004). A teaching fence is how the documentation shows one: it is classified and never counts as a conforming positive. A marker on an ordinary example would hide it from positive checking.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG4004: Teaching examples require authenticated compiler classification","header":"Why it matters","id":"/rules/RG4004/#RG4004-rationale"},"/rules/RG5003/#RG5003-rationale":{"contents":"The explanation states what the formal statement says; the intent states what it is required to say. Comparing the two, and both with the declaration, exposes statements that are faithfully explained but wrong (standard §5.2).\n\n","context":"Regula rule reference\u0009Rule index\u0009RG5003: Registered public material declarations require an Intent section","header":"Why it matters","id":"/rules/RG5003/#RG5003-rationale"}});